use vstd::prelude::*;

verus! {

    // Reverse a vector of i8 values.
    // Postconditions:
    // 1) The result has the same length as the input.
    // 2) For every index k in [0, n), rev[k] == s[n-1-k].
    fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
        ensures
            rev.len() == s.len(),
            forall |k: usize| k < s.len() ==> rev[k] == s[s.len() - 1 - k],
    {
        let n: usize = s.len();
        let mut rev: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                // We never overshoot
                i <= n,
                // rev has collected exactly i elements so far
                rev.len() == i,
                // Those i elements are the last i elements of s, in reverse
                forall |j: usize| j < i ==> rev[j] == s[n - 1 - j],
            decreases n - i
        {
            // pick the next element from the end of s
            let elt: i8 = s[n - 1 - i];
            rev.push(elt);
            i += 1;
        }
        rev
    }

} // end verus!

